messages.content:
Write social media copy for this event:
Title: {{$json.title}}
Summary: {{$json.summary}}
Date: {{$json.date}}
URL: {{$json.url}}
Modality: {{$json.modality}}

Please provide:
1. Facebook post (2-3 paragraphs)
2. Instagram caption (with hashtags)
3. WhatsApp message (short, with link)
4. LINE message (short, with link)

parameters.jsCode:
const response = $input.first().json;
const content = response.choices[0].message.content;

// Split by platform headers
const sections = content.split(/\d+\.\s+/);

return [{
  json: {
    facebook: sections[1] || '',
    instagram: sections[2] || '',
    whatsapp: sections[3] || '',
    line: sections[4] || '',
    raw: content
  }
}];
